query PullRequestQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      id
      __typename
      ... {
        title
        __typename
        ... {
          isDraft
          state
        }
        updatedAt
        author {
          login
        }
        additions
        deletions
        reviewDecision
        commits(last: 1) {
          nodes {
            commit {
              statusCheckRollup {
                state
              }
            }
          }
        }
      }
      body
      createdAt
      baseRefName
      headRefName
      baseRefOid
      headRefOid
      headRepository {
        nameWithOwner
      }
      changedFiles
      mergeable
      mergeStateStatus
      viewerCanClose
      viewerCanReopen
      viewerCanUpdate
      viewerCanMergeAsAdmin
      viewerDidAuthor
      maintainerCanModify
      isCrossRepository
      labels(first: 20) {
        totalCount
        nodes {
          name
          color
        }
      }
      milestone {
        number
        title
      }
    }
    mergeCommitAllowed
    squashMergeAllowed
    rebaseMergeAllowed
    viewerDefaultMergeMethod
    viewerPermission
  }
}
